 metrics=read_csv(data/'model_metrics.csv');complexity=read_csv(data/'model_complexity.csv');classwise=read_csv(data/'classwise_metrics.csv');roc=read_csv(data/'roc_pr_metrics.csv');counts=read_csv(data/'approved_dataset_counts.csv');by={r['model']:r for r in metrics}
