 validation_table='\n'.join(f"| {r['model_name']} | {float(r['accuracy']):.4f} | {float(r['macro_f1']):.4f} | {float(r['balanced_accuracy']):.4f} | {float(r['macro_AUROC_OvR']):.4f} | {float(r['macro_AUPRC_average_precision']):.4f} | {float(r['MEL_recall']):.4f} | {float(r['SCC_recall']):.4f} | {r['best_epoch']}/{r['total_epochs']} | {float(r['training_wall_seconds'])/60:.2f} |" for r in metrics)
